-- PyroGuard v17 (2026-11-23): fire incident history for Malabon City and Caloocan City
-- (from the team's "Fire incidents" research document, with its news references).
-- Locations are barangay-level map points. Safe to run more than once.

-- Official / news records have no app reporter (reported_by is null); residents' entries keep theirs.
alter table public.pyroguard_area_incidents alter column reported_by drop not null;
alter table public.pyroguard_area_incidents
  add column if not exists city            text,
  add column if not exists location_text   text,
  add column if not exists alarm_level     text,
  add column if not exists details         text check (details is null or char_length(details) <= 1000),
  add column if not exists reference       text check (reference is null or char_length(reference) <= 1000),
  add column if not exists date_precision  text not null default 'day' check (date_precision in ('day','month')),
  add column if not exists location_approx boolean not null default false,
  add column if not exists verified        boolean not null default true,
  add column if not exists seed_key        text;
create unique index if not exists pyroguard_area_incidents_seed_key_uidx
  on public.pyroguard_area_incidents (seed_key);
create index if not exists pyroguard_area_incidents_city_idx
  on public.pyroguard_area_incidents (city, occurred_on desc);

-- 30 recorded incidents (18 Malabon, 12 Caloocan)
on conflict (seed_key) do update set city=excluded.city, occurred_on=excluded.occurred_on,
  date_precision=excluded.date_precision, location_text=excluded.location_text, latitude=excluded.latitude,
  longitude=excluded.longitude, location_approx=excluded.location_approx, alarm_level=excluded.alarm_level,
  description=excluded.description, details=excluded.details, reference=excluded.reference,
  verified=excluded.verified, source=excluded.source, incident_type=excluded.incident_type;
